BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create function pg_temp.i(n int)returns uuid language sql immutable as $$select('ee810000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table st(k text primary key,v jsonb);grant all on st,assertion_count to service_role;
insert into public.organizations(id,name)values(pg_temp.i(1),'BI CSV SQL fixture'),(pg_temp.i(2),'BI CSV other fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select pg_temp.i(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','bi-csv-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(101,104)n;
insert into public.profiles(id,org_id,role)select pg_temp.i(n),pg_temp.i(case when n=103 then 2 else 1 end),case when n=102 then'viewer'else'admin'end from generate_series(101,104)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role;
insert into public.properties(id,org_id,name)values(pg_temp.i(201),pg_temp.i(1),'BI CSV SQL property'),(pg_temp.i(202),pg_temp.i(2),'BI CSV other property');
create function pg_temp.original()returns jsonb language sql immutable as $$select'{"filename":"exact.csv","csvContent":"EXACT private original export","platform":"google_ads","sourceAccountId":"1234567890","currencyCode":"USD","campaignName":"Campaign"}'::jsonb$$;
create function pg_temp.preview(account text default'1234567890',spend numeric default 12.5)returns jsonb language sql immutable as $$select jsonb_build_object('kind','daily','platform','google_ads','sourceAccountId',account,'currencyCode','USD','reportType','time_series','parserVersion','native-fixture-v1','dateRange',jsonb_build_object('start','2026-09-01','end','2026-09-01'),'rows',jsonb_build_array(jsonb_build_object('date','2026-09-01','campaign_id','provider-id','campaign_name','Actual campaign','impressions',100,'clicks',10,'spend',spend,'conversions',0.125)))$$;
create function pg_temp.dimension(account text default'1234567890')returns jsonb language sql immutable as $$select pg_temp.preview(account)||jsonb_build_object('kind','dimension','reportType','devices','rows',jsonb_build_array(jsonb_build_object('campaign_id','provider-id','campaign_name','Actual campaign','dimension_key','device','dimension_value','Mobile','date_range_start','2026-09-01','date_range_end','2026-09-01','metrics',jsonb_build_object('clicks',3,'spend',12.5))))$$;
create function pg_temp.prepare(n int,preview jsonb default pg_temp.preview(),actor int default 101,parent int default null)returns jsonb language sql as $$select public.prepare_bi_csv(pg_temp.i(n),pg_temp.i(actor),pg_temp.i(201),pg_temp.original(),preview,pg_temp.i(parent))$$;
create function pg_temp.read_it(n int default null,kind text default'history',offset_n int default 0,actor int default 101,hash text default null)returns jsonb language sql as $$select public.read_bi_csv(pg_temp.i(actor),pg_temp.i(201),pg_temp.i(n),null,kind,offset_n,hash)$$;
create function pg_temp.decide(n int,target int,op text default'apply',actor int default 101)returns jsonb language plpgsql as $$declare r public.bi_csv_imports;begin select*into r from public.bi_csv_imports where id=pg_temp.i(target);return public.decide_bi_csv(pg_temp.i(n),pg_temp.i(actor),pg_temp.i(201),pg_temp.i(target),jsonb_build_object('operation',op,'previewHash',r.preview_hash,'targetHash',r.target_hash,'reason','Reviewed original, reporting account and exact rows.'));end$$;
set local role service_role;
select pg_temp.check_it(pg_temp.prepare(301)->>'status'='preview','exact preview saved');
select pg_temp.check_it((select count(*)=0 from public.fact_marketing_performance where property_id=pg_temp.i(201)),'preview does not write business rows');
select pg_temp.check_it(pg_temp.prepare(301)->>'state'='replayed','lost preview reply replays');
select pg_temp.check_it(public.prepare_bi_csv(pg_temp.i(301),pg_temp.i(101),pg_temp.i(201),pg_temp.original()||'{"filename":"changed.csv"}',pg_temp.preview())->>'state'='request_conflict','same ID cannot replace original');
select pg_temp.check_it(pg_temp.prepare(302,pg_temp.preview(),102)->>'state'='forbidden','viewer cannot import');
select pg_temp.check_it(pg_temp.prepare(302,pg_temp.preview(),103)->>'state'='forbidden','cross tenant cannot import');
select pg_temp.check_it(pg_temp.read_it(301,'history',0,102)->'record'->'original'->>'csvContent'='EXACT private original export','viewer can inspect actual private source in property');
select pg_temp.check_it(pg_temp.read_it(301,'history',0,103)->>'state'='forbidden','other tenant denied original');
select pg_temp.check_it(pg_temp.decide(401,301)->>'rowsApplied'='1','exact one-row reviewed application');
select pg_temp.check_it((select count(*)=1 and sum(conversions)=0.125 from public.fact_marketing_performance where property_id=pg_temp.i(201)),'fractional actual outcome retained');
select pg_temp.check_it((select count(*)=1 from public.marketing_data_uploads where retained_import_id=pg_temp.i(301)),'upload log commits with applied source');
select pg_temp.check_it(pg_temp.decide(401,301)->>'status'='applied','lost decision reply replays');
select pg_temp.check_it((select count(*)=1 from public.marketing_data_uploads where retained_import_id=pg_temp.i(301)),'replay does not create another upload');
select pg_temp.check_it(pg_temp.read_it(301,'after')->>'count'='1','accepted full after state inspectable');
select pg_temp.check_it(pg_temp.read_it(301,'decisions')->>'count'='1','applied actor and reason retained');
select pg_temp.check_it(pg_temp.prepare(302,pg_temp.preview('1234567890',20))->>'status'='preview','replacement preview captures current target');
select pg_temp.check_it(pg_temp.read_it(302,'before')->'items'->0->>'spend'='12.50','actual before value retained');
select pg_temp.check_it(pg_temp.prepare(303,pg_temp.preview('1234567890',30))->>'status'='preview','concurrent preview captures same target');
select pg_temp.check_it(pg_temp.decide(402,302)->>'status'='applied','reviewed replacement applied');
select pg_temp.check_it(pg_temp.decide(403,303)->>'state'='source_changed','stale target cannot overwrite later import');
select pg_temp.check_it(pg_temp.prepare(304,pg_temp.preview('1234567890',30),101,303)->>'status'='preview','explicit rebase retains parent and same original');
select pg_temp.check_it(pg_temp.decide(404,304)->>'status'='applied','new review applies updated target');
select pg_temp.check_it(pg_temp.decide(405,303,'discard')->>'status'='discarded','stale draft can be discarded without altering facts');
select pg_temp.check_it((select spend=30 from public.fact_marketing_performance where property_id=pg_temp.i(201)),'discard leaves current facts unchanged');
select pg_temp.check_it(public.prepare_bi_csv(pg_temp.i(305),pg_temp.i(101),pg_temp.i(201),null,null,null,true)->>'status'='cancelled','unused source identity closed');
select pg_temp.check_it(pg_temp.prepare(305)->>'status'='cancelled','late preview fenced');
select pg_temp.check_it(public.decide_bi_csv(pg_temp.i(406),pg_temp.i(101),pg_temp.i(201),null,'{"operation":"cancel"}')->>'status'='cancelled_request','unused decision closed');
select pg_temp.check_it(pg_temp.decide(406,301)->>'status'='cancelled_request','late application fenced');
select pg_temp.check_it(pg_temp.prepare(306,pg_temp.preview('9876543210',40))->>'status'='preview','other source account preview');
select pg_temp.check_it(pg_temp.decide(407,306)->>'status'='applied','other source account applied separately');
select pg_temp.check_it((select count(*)=2 from public.fact_marketing_performance where property_id=pg_temp.i(201)),'accounts never merge');
select pg_temp.check_it(pg_temp.prepare(307,pg_temp.dimension())->>'status'='preview','dimension source preview');
select pg_temp.check_it(pg_temp.decide(408,307)->>'status'='applied','dimension source applied');
select pg_temp.check_it(pg_temp.prepare(308,pg_temp.dimension('9876543210'))->>'status'='preview','other dimension account preview');
select pg_temp.check_it(pg_temp.decide(409,308)->>'status'='applied','other dimension account applied');
select pg_temp.check_it((select count(*)=2 from public.fact_marketing_extended where property_id=pg_temp.i(201)),'extended identity includes source account');
select pg_temp.check_it(pg_temp.prepare(309,pg_temp.dimension()||jsonb_build_object('rows',(pg_temp.dimension()->'rows')||(pg_temp.dimension()->'rows')))->>'status'='preview','duplicate native source retained for validation trial');
select pg_temp.throws(format('select pg_temp.decide(%s,%s)',410,309),'duplicate import fails atomically');
select pg_temp.check_it((select count(*)=2 from public.fact_marketing_extended where property_id=pg_temp.i(201)),'duplicate failure leaves earlier facts');
select pg_temp.check_it(pg_temp.read_it(309)->'record'->>'state'='preview','failed apply keeps original review recoverable');
-- Injected recording error must roll back facts and upload log as one transaction.
reset role;
create function pg_temp.fail_csv_action()returns trigger language plpgsql as $$begin if new.id=pg_temp.i(411)then raise exception 'injected recording failure';end if;return new;end$$;
create trigger csv_action_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_csv_action();
set local role service_role;
select pg_temp.check_it(pg_temp.prepare(310,pg_temp.preview('1234567890',88))->>'status'='preview','atomic failure source prepared');
select pg_temp.throws(format('select pg_temp.decide(%s,%s)',411,310),'recording failure aborts complete import');
select pg_temp.check_it((select spend=30 from public.fact_marketing_performance where property_id=pg_temp.i(201)and source_account_id='1234567890'),'facts roll back with action failure');
select pg_temp.check_it((select count(*)=0 from public.marketing_data_uploads where retained_import_id=pg_temp.i(310)),'upload log rolls back with action failure');
select pg_temp.check_it(pg_temp.read_it(310)->'record'->>'state'='preview','source remains reviewable after failed action');
select set_config('p11.bi_csv_scope','',true);
select pg_temp.throws(format('update public.bi_csv_imports set original=%L where id=%L','{}',pg_temp.i(301)),'original cannot be rewritten');
select pg_temp.throws(format('delete from public.bi_csv_imports where id=%L',pg_temp.i(301)),'retained source cannot be deleted');
select set_config('p11.bi_csv_scope',pg_temp.i(201)::text,true);
select pg_temp.throws(format('update public.bi_csv_imports set preview=%L where id=%L','{}',pg_temp.i(310)),'even active scope cannot replace preview');
select pg_temp.throws(format('update public.bi_csv_commands set result=%L where id=%L','{}',pg_temp.i(401)),'commands immutable');
insert into st values('page',pg_temp.read_it());
select public.prepare_bi_csv(pg_temp.i(500+n),pg_temp.i(101),pg_temp.i(201),null,null,null,true)from generate_series(1,27)n;
select pg_temp.check_it(pg_temp.read_it()->>'count'='37','full history count');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_it(null,'history',25)->'items')=12,'second complete history page');
select pg_temp.check_it(pg_temp.read_it(null,'history',25,101,(select v->>'hash'from st where k='page'))->>'state'='history_changed','changed history fences continuation');
select pg_temp.check_it((select bool_and(not training_eligible)and bool_and(evidence='server_confirmed')from public.shared_action_events where property_id=pg_temp.i(201)and action like'bi.csv.%'),'attributed history remains training ineligible');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id=pg_temp.i(201)and(request::text||coalesce(before_state::text,'')||coalesce(after_state::text,'')||result::text)like'%EXACT private%'),'shared action excludes private originals');
reset role;
select pg_temp.check_it(not has_table_privilege('authenticated','public.bi_csv_imports','SELECT'),'private originals require scoped reader');
select pg_temp.check_it(not has_function_privilege('authenticated','public.prepare_bi_csv(uuid,uuid,uuid,jsonb,jsonb,uuid,boolean)','EXECUTE'),'previews service-only');
select set_config('p11.team_scope',pg_temp.i(1)::text,true);update public.profiles set role='viewer'where id=pg_temp.i(101);
select pg_temp.check_it(pg_temp.decide(412,310)->>'state'='forbidden','revoked role blocks final application');
select pg_temp.check_it(pg_temp.prepare(301)->>'state'='forbidden','revoked role blocks preparation replay');
select pg_temp.check_it(pg_temp.read_it(301)->'record'->>'state'='applied','current viewer retains historical read');

select pg_temp.check_it(public.prepare_bi_csv(pg_temp.i(700),pg_temp.i(104),pg_temp.i(201),pg_temp.original(),pg_temp.preview()-'kind')->>'state'='invalid_input','missing kind rejected');
select pg_temp.check_it(public.prepare_bi_csv(pg_temp.i(700),pg_temp.i(104),pg_temp.i(201),pg_temp.original(),pg_temp.preview()-'sourceAccountId')->>'state'='invalid_input','missing source account rejected');
insert into public.marketing_data_uploads(property_id,platform,report_type,file_name,rows_imported)select pg_temp.i(201),'google_ads','time_series','legacy-'||n||'.csv',n from generate_series(1,28)n;
select pg_temp.check_it(pg_temp.read_it(null,'legacy')->>'count'='28','earlier uploads remain complete and separate');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_it(null,'legacy',25)->'items')=3,'older upload last page reachable');
select pg_temp.check_it(pg_temp.read_it(null,'legacy',0,103)->>'state'='forbidden','legacy history tenant isolation');
insert into public.fact_marketing_extended(property_id,channel_id,campaign_name,report_type,dimension_key,dimension_value,date_range_start,date_range_end,metrics)values(pg_temp.i(201),'google_ads','Unknown earlier campaign','devices','value','Mobile','2026-09-01','2026-09-01','{"spend":88}');
select pg_temp.check_it(pg_temp.prepare(701,pg_temp.dimension(),104)->>'status'='preview','legacy overlap retained in exact preview');
select pg_temp.check_it(pg_temp.decide(702,701,'apply',104)->>'state'='legacy_review_required','unowned dimension overlap is held despite older dimension key');
select pg_temp.check_it((select count(*)=3 from public.fact_marketing_extended where property_id=pg_temp.i(201)),'legacy row remains unchanged during hold');
select pg_temp.check_it(pg_temp.prepare(704,pg_temp.preview('1234567890',12.505),104)->>'state'='invalid_input','fractional-cent preview cannot silently round during application');
select n as assertions_passed from assertion_count;
ROLLBACK;
